import {getAction} from '@madou/catalog';
import {createGame,gameStats} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const borderWoodPhysicalScenarios=['border-setup','border-turn','wood-setup','wood-turn','border-grant-hand','border-grant-field','border-army','wood-army','wood-mental','wood-mental-destroy'] as const;
export type BorderWoodPhysicalScenario=typeof borderWoodPhysicalScenarios[number];
export function isBorderWoodPhysicalScenario(name:string):name is BorderWoodPhysicalScenario{return (borderWoodPhysicalScenarios as readonly string[]).includes(name);}
export function borderWoodPhysicalMode(name:BorderWoodPhysicalScenario){const border=name.startsWith('border');return{card:border?'a2-p19-r2c2':'a2-p19-r2c3',name:border?'辺境警備隊':'ウッドゴーレム',level:border?3:4,hp:border?1:5,attributes:border?['人']:['ゴ','地','木'],attackLevel:border?2:3,attackDamage:border?2:5,attackAttributes:border?['近','戦']:['近','戦','格'],grant:name.includes('-grant-'),army:name.endsWith('-army'),mental:name.includes('-mental'),destroy:name.endsWith('-destroy'),initial:name.endsWith('-setup')||name.endsWith('-field')||name.includes('-mental')};}
/** Every scenario starts in real initial placement; tests issue all placement and turn commands. */
export function makeBorderWoodPhysicalScenario(name:BorderWoodPhysicalScenario,players:{id:string;name:string}[],options:{dwarf?:boolean;level?:number;owner?:string;warrior?:number}={}){
 const m=borderWoodPhysicalMode(name),s=createGame(players,entropy(),{startingSeat:0}),[a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];for(const [i,p] of players.entries())assignCharacter(s,p.id,[options.dwarf?'魔導王ガイナス':options.owner??'魔聖母ディア',options.dwarf?'魔聖母ディア':m.mental?(m.destroy?'占星術師のアルセイル':'餓狼ヨーツルム'):'白魔術師シェリム','凍気のアイエル','侍大将のシン'][i]!);for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit=20+14-gameStats(s,p.id).spirit;}if(options.level!==undefined)s.players[b]!.permanent!.warrior_level=20+options.level-gameStats(s,b).warrior_level;
 if(options.warrior!==undefined)s.players[a]!.permanent!.warrior_level=20+options.warrior-gameStats(s,a).warrior_level;
 const keep=[takeCard(s,a,m.card),takeCard(s,a,'a2-p24-r1c3'),takeCard(s,a,'a2-p22-r1c1'),takeCard(s,a,m.army?'a2-p05-r2c2':m.mental?'a2-p18-r3c3':'a2-p23-r1c1'),takeCard(s,a,'a2-p07-r1c1'),takeCard(s,b,'a2-p24-r1c2'),takeCard(s,b,'a2-p24-r2c1'),takeCard(s,b,'a2-p21-r2c3'),...(m.mental?[takeCard(s,b,m.destroy?'a2-p13-r1c2':'a2-p16-r2c1')]:[]),takeCard(s,d,'a2-p02-r2c3')];for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];return s;
}
